const KEY='thesis.workspace.v1';let storageAvailable=true;let saved=null;try{saved=JSON.parse(localStorage.getItem(KEY)||'null');}catch(e){storageAvailable=false;}
const isThesis=t=>t&&typeof t.id==='string'&&typeof t.title==='string'&&typeof t.vertical==='string'&&typeof t.summary==='string'&&['active','draft'].includes(t.status)&&Object.hasOwn(tones,t.color)&&['high','medium','early'].includes(t.conviction)&&Number.isFinite(t.checkMin)&&Number.isFinite(t.checkMax)&&t.checkMin<=t.checkMax&&typeof t.stages==='string'&&typeof t.geography==='string';
let theses=Array.isArray(saved?.theses)?saved.theses.filter(isThesis):structuredClone(initial);
let settings={fund:typeof saved?.settings?.fund==='string'?saved.settings.fund:'Northstar Ventures',person:typeof saved?.settings?.person==='string'?saved.settings.person:'Nidhish Gautam'};
let filter='all',vertical='',query='',view='grid',editingId=null,toastTimer;
function notify(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200);}
function persist(){try{localStorage.setItem(KEY,JSON.stringify({theses,settings}));storageAvailable=true;return true;}catch(e){storageAvailable=false;notify('Browser storage is unavailable. Export your theses to keep a copy.');return false;}}
function money(value){return new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',notation:'compact',maximumFractionDigits:2}).format(value);}
function dateLabel(date){const d=new Date(date);if(!Number.isFinite(d.getTime()))return 'Recently';return d.toLocaleDateString('en-US',{month:'short',day:'numeric'});}
function card(t){const tone=tones[t.color];const conviction={high:'High conviction',medium:'Building conviction',early:'Early exploration'}[t.conviction];return `<article class="thesis-card glass" style="--tone:${tone.tone};--wash:${tone.wash}"><div class="card-top"><div class="vertical-icon">${svg(tone.icon)}</div><span class="status ${t.status==='draft'?'draft':''}">${t.status==='active'?'Active thesis':'Draft'}</span></div><button class="card-title" data-edit="${esc(t.id)}">${esc(t.title)}</button><p class="card-description">${esc(t.summary)}</p><div class="stage-tags">${t.stages.split(',').map(s=>`<span class="stage-tag">${esc(s.trim())}</span>`).join('')}</div><div class="card-details"><div><div class="detail-label">${svg('wallet')}Check size</div><div class="detail-value">${money(t.checkMin)} – ${money(t.checkMax)}</div></div><div><div class="detail-label">${svg('pin')}Geography</div><div class="detail-value" title="${esc(t.geography)}">${esc(t.geography)}</div></div></div><div class="card-footer"><span class="conviction"><span class="signal ${t.conviction}"><i></i><i></i><i></i></span>${conviction}</span><div class="card-footer-right"><span>${dateLabel(t.updated)}</span>${svg('arrow')}</div></div></article>`;}
function render(){const active=theses.filter(t=>t.status==='active').length,high=theses.filter(t=>t.conviction==='high').length,drafts=theses.filter(t=>t.status==='draft').length;$('#nav-total').textContent=theses.length;$('#nav-high').textContent=high;$('#nav-draft').textContent=drafts;$('#tab-total').textContent=theses.length;$('#fund-name').textContent=settings.fund;$('#profile-name').textContent=settings.person;$('.fund-icon').textContent=settings.fund.charAt(0).toUpperCase();document.querySelectorAll('.avatar').forEach(el=>el.textContent=settings.person.split(/\s+/).filter(Boolean).map(s=>s[0]).slice(0,2).join('').toUpperCase());
const stats=[['Active verticals',new Set(theses.filter(t=>t.status==='active').map(t=>t.vertical)).size,'in your investment universe','layers'],['High conviction',high,'perspectives with a clear edge','spark'],['Work in progress',drafts,'ideas taking shape','file']];$('#stats').innerHTML=stats.map(([label,value,sub,icon])=>`<div class="stat glass"><div><div class="stat-label">${label}</div><div class="stat-value">${value}<small>${sub}</small></div></div><div class="stat-icon">${svg(icon)}</div></div>`).join('');
$('#vertical-nav').innerHTML=[...new Set(theses.map(t=>t.vertical))].map(v=>{const t=theses.find(t=>t.vertical===v);return `<button class="vertical-item ${vertical===v?'selected':''}" data-vertical="${esc(v)}" style="--tone:${tones[t.color].tone}"><span class="color-dot"></span>${esc(v)}</button>`;}).join('');
const filtered=theses.filter(t=>(filter==='all'||(filter==='high'?t.conviction==='high':t.status===filter))&&(!vertical||t.vertical===vertical)&&(!query||[t.title,t.vertical,t.summary,t.stages,t.geography,t.whyNow,t.criteria,t.risks].join(' ').toLowerCase().includes(query.toLowerCase())));
$('#heading-count').textContent=filtered.length;$('#thesis-grid').classList.toggle('list-mode',view==='list');$('#thesis-grid').innerHTML=filtered.map(card).join('')+(filtered.length||(!query&&!vertical&&filter==='all')?`<button class="new-card" id="new-card"><span>${svg('plus')}</span><strong>A new perspective</strong><p>Explore a vertical. Define your edge.<br>Build your next investment thesis.</p></button>`:'');$('#empty-state').hidden=filtered.length>0||(!query&&!vertical&&filter==='all');
$('#filter-context').hidden=!vertical;$('#filter-context').innerHTML=vertical?`Showing ${esc(vertical)} <button id="clear-vertical">Clear vertical ×</button>`:'';document.querySelectorAll('.nav-item').forEach(el=>el.classList.toggle('selected',el.dataset.filter===filter&&!vertical));document.querySelectorAll('.tab').forEach(el=>el.classList.toggle('active',el.dataset.tab===filter));$('#grid-view').classList.toggle('active',view==='grid');$('#list-view').classList.toggle('active',view==='list');$('#grid-view').setAttribute('aria-pressed',view==='grid');$('#list-view').setAttribute('aria-pressed',view==='list');$('#storage-status').textContent=storageAvailable?'Illustrative starter theses · changes saved in this browser':'Changes are temporary · export to keep a copy';
}
function openEditor(id=null){editingId=id;const t=theses.find(x=>x.id===id);const form=$('#thesis-form');form.reset();$('#form-error').textContent='';$('#dialog-title').textContent=t?'Refine your thesis':'A new point of view';$('#delete-thesis').hidden=!t;$('#export-one').hidden=!t;if(t){for(const key of ['title','vertical','status','summary','stages','geography','checkMin','checkMax','conviction','color','whyNow','criteria','risks'])form.elements.namedItem(key).value=t[key]??'';}else{form.elements.namedItem('stages').value='Pre-seed, Seed';form.elements.namedItem('conviction').value='medium';}$('#thesis-dialog').showModal();}
function markdown(t){return `# ${t.title}\n\n**Fund:** ${settings.fund}\n**Author:** ${settings.person}\n**Updated:** ${t.updated}\n\n## Investment snapshot\n\n- Vertical: ${t.vertical}\n- Status: ${t.status}\n- Conviction: ${{high:'High',medium:'Building',early:'Early exploration'}[t.conviction]}\n- Stages: ${t.stages}\n- Geography: ${t.geography}\n- Check size: ${money(t.checkMin)}–${money(t.checkMax)} USD\n\n## Core thesis\n\n${t.summary}\n\n## Why now?\n\n${t.whyNow||'Not yet defined.'}\n\n## What we look for\n\n${t.criteria||'Not yet defined.'}\n\n## Risks & disconfirming evidence\n\n${t.risks||'Not yet defined.'}\n`;}
function download(text,filename){const blob=new Blob([text],{type:'text/markdown;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Markdown export downloaded.');}
$('#thesis-form').addEventListener('submit',event=>{event.preventDefault();const data=Object.fromEntries(new FormData(event.target));for(const key of Object.keys(data))data[key]=data[key].trim();if(['title','vertical','summary','stages','geography'].some(k=>!data[k])){$('#form-error').textContent='Please complete the title, vertical, thesis, stages, and geography.';return;}data.checkMin=Number(data.checkMin);data.checkMax=Number(data.checkMax);if(data.checkMin>data.checkMax){$('#form-error').textContent='The maximum check must be at least the minimum check.';return;}const t={...data,id:editingId||crypto.randomUUID(),updated:stamp()};if(editingId)theses=theses.map(x=>x.id===editingId?t:x);else theses.unshift(t);const saved=persist();render();$('#thesis-dialog').close();if(saved)notify(editingId?'Thesis updated. Conviction, refined.':'Your new thesis is ready to build on.');});
$('#new-thesis').addEventListener('click',()=>openEditor());document.querySelectorAll('.close-dialog').forEach(b=>b.addEventListener('click',()=>$('#thesis-dialog').close()));$('#thesis-grid').addEventListener('click',e=>{const edit=e.target.closest('[data-edit]');if(edit)openEditor(edit.dataset.edit);else if(e.target.closest('#new-card'))openEditor();});
$('#delete-thesis').addEventListener('click',()=>{if(!editingId)return;const t=theses.find(t=>t.id===editingId);if(!confirm(`Delete “${t.title}”? This removes the thesis from this browser.`))return;theses=theses.filter(t=>t.id!==editingId);persist();render();$('#thesis-dialog').close();notify('Thesis deleted.');});
$('#export-one').addEventListener('click',()=>{const t=theses.find(t=>t.id===editingId);if(t)download(markdown(t),`${t.title.toLowerCase().replace(/[^a-z0-9]+/g,'-')}-thesis.md`);});$('#export-all').addEventListener('click',()=>{if(!theses.length){notify('Create a thesis to export first.');return;}download(`# ${settings.fund} — Investment theses\n\nExported ${new Date().toLocaleDateString()}\n\n${theses.map(markdown).join('\n---\n\n')}`,'investment-theses.md');});
$('.brand').addEventListener('click',e=>{e.preventDefault();resetFilters();});document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;vertical='';render();}));document.querySelectorAll('[data-tab]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.tab;render();}));$('#vertical-nav').addEventListener('click',e=>{const b=e.target.closest('[data-vertical]');if(b){vertical=b.dataset.vertical;filter='all';render();}});$('#filter-context').addEventListener('click',e=>{if(e.target.closest('#clear-vertical')){vertical='';render();}});$('#search').addEventListener('input',e=>{query=e.target.value;render();});function resetFilters(){query='';vertical='';filter='all';$('#search').value='';render();}$('#clear-filters').addEventListener('click',resetFilters);$('#grid-view').addEventListener('click',()=>{view='grid';render();});$('#list-view').addEventListener('click',()=>{view='list';render();});document.addEventListener('keydown',e=>{if(e.key==='/'&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName)&&!document.querySelector('dialog[open]')){e.preventDefault();$('#search').focus();}});
function openSettings(){const form=$('#settings-form');form.elements.namedItem('fund').value=settings.fund;form.elements.namedItem('person').value=settings.person;$('#settings-dialog').showModal();}$('#workspace-settings').addEventListener('click',openSettings);$('#profile-button').addEventListener('click',openSettings);$('#close-settings').addEventListener('click',()=>$('#settings-dialog').close());$('#settings-form').addEventListener('submit',e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));if(!data.fund.trim()||!data.person.trim())return;settings={fund:data.fund.trim(),person:data.person.trim()};const saved=persist();render();$('#settings-dialog').close();if(saved)notify('Workspace settings saved.');});
hydrateIcons();render();
